// spi_driver.sv - generated by uvm_full_tb_generator.py, filled in as an SPI SLAVE
//   The SoC SPI master (IPs/spi) is mode 0, MSB first: SCLK idles low,
//   data sampled on the rising edge and changed on the falling edge.
//   Behaves like a small memory: MISO returns the bytes the master wrote in the
//   PREVIOUS frame (or bytes from a sequence). Optional single MISO bit flip.
//   uvm_config_db knobs (int): spi_inject_miso_err, spi_err_frame, spi_err_byte, spi_err_bit
class spi_driver extends uvm_driver #(spi_item);
virtual spi_if vif;
int unsigned inject_miso_err = 0, err_frame = 1, err_byte = 0, err_bit = 0;
bit [7:0]    last_frame[$];
int unsigned frame_count;
`uvm_component_utils(spi_driver)
function new(string n,uvm_component p);super.new(n,p);endfunction

function void build_phase(uvm_phase phase);
  super.build_phase(phase);
  if (!uvm_config_db#(virtual spi_if)::get(this, "", "spi_vif", vif))
    `uvm_fatal("NOVIF", "spi_vif not set in uvm_config_db")
  void'(uvm_config_db#(int unsigned)::get(this, "", "spi_inject_miso_err", inject_miso_err));
  void'(uvm_config_db#(int unsigned)::get(this, "", "spi_err_frame", err_frame));
  void'(uvm_config_db#(int unsigned)::get(this, "", "spi_err_byte",  err_byte));
  void'(uvm_config_db#(int unsigned)::get(this, "", "spi_err_bit",   err_bit));
endfunction

task run_phase(uvm_phase phase);
  vif.spi_miso_i <= 1'b0;
  wait (vif.rst_n === 1'b1);
  forever begin
    @(negedge vif.spi_cs_no);
    respond_frame();
  end
endtask

function bit miso_bit(ref bit [7:0] out_q[$], input int byte_i, input int bit_i);
  bit b = (byte_i < out_q.size()) ? out_q[byte_i][bit_i] : 1'b0;
  if (inject_miso_err && frame_count == err_frame && byte_i == err_byte && bit_i == err_bit) begin
    `uvm_info("SPI_DRV", $sformatf("FAULT: flipping MISO frame %0d byte %0d bit %0d",
                                   frame_count, byte_i, bit_i), UVM_LOW)
    b = ~b;
  end
  return b;
endfunction

task respond_frame();
  bit [7:0] out_q[$];
  bit [7:0] in_q[$];
  bit [7:0] sh;
  int nbit = 0, nbyte = 0;

  seq_item_port.try_next_item(req);              // response from a sequence, if any
  if (req != null) begin
    foreach (req.resp_bytes[i]) out_q.push_back(req.resp_bytes[i]);
    seq_item_port.item_done();
  end else begin
    out_q = last_frame;                          // else: echo the previous frame
  end

  vif.spi_miso_i <= miso_bit(out_q, 0, 7);       // MSB valid before the first edge
  forever begin
    @(posedge vif.spi_sclk_o or posedge vif.spi_cs_no);
    if (vif.spi_cs_no) break;
    sh = {sh[6:0], vif.spi_mosi_o};
    if (++nbit == 8) begin in_q.push_back(sh); nbit = 0; nbyte++; end
    @(negedge vif.spi_sclk_o or posedge vif.spi_cs_no);
    if (vif.spi_cs_no) break;
    vif.spi_miso_i <= miso_bit(out_q, nbyte, 7 - nbit);
  end
  vif.spi_miso_i <= 1'b0;
  if (nbit != 0) `uvm_warning("SPI_DRV", $sformatf("frame %0d ended mid-byte", frame_count))
  last_frame = in_q;
  frame_count++;
endtask
endclass
